#pragma once

// XexImage of retrobridge_host (spec menu-xex, X002): checks a .xex and wraps it
// in the virtual disk the menu serves in D1. The disk is an ATR of 128-byte
// sectors: the boot sectors of the 6502 loader (xex_loader.inc, generated by
// tools/make_xex_loader.py) with the .xex length patched in, then the .xex
// bytes as they are, sector after sector. The loader walks them on the Atari.
//
// Format (docs/fuentes.md, menu-xex): a $FFFF header first, optional before
// later segments; each segment is start, end (inclusive, little-endian) and
// end - start + 1 data bytes. Pure function: no files, no network, no SIO.

#include <cstdint>

#include "rb/menu/memory_image_store.hpp"
#include "rb/core/span.hpp"

namespace rb::host {

enum class XexResult : uint8_t {
    Ok,
    Invalid,       // no $FFFF at the start, start > end, a cut header or cut data (AC8)
    Incompatible,  // a segment touches the loader and its buffer, or page 1 (AC9)
    TooLarge,      // the disk would pass 65535 sectors
    NoMemory,      // the image buffer could not be allocated
};

struct XexWrap {
    XexResult result = XexResult::Invalid;
    uint32_t segments = 0;  // segments found (0 unless Ok or Incompatible)
};

class XexImage {
public:
    static constexpr uint32_t kSectorSize = 128;
    static constexpr uint32_t kHeaderSize = 16;
    static constexpr uint32_t kMaxSectors = 65535;
    // Page 1, the 6502 stack: a segment there would overwrite the loader's return addresses
    // (decided by the owner on 2026-11-20, X004).
    static constexpr uint32_t kStackLow = 0x0100;
    static constexpr uint32_t kStackHigh = 0x01FF;

    // On Ok, `out` holds the whole ATR (header included); otherwise it is left as it was.
    // Checked in this order: TooLarge (by size alone), Invalid, Incompatible, NoMemory.
    static XexWrap wrap(rb::core::Span<const uint8_t> xex, ImageBuffer& out) noexcept;
};

}  // namespace rb::host
